<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/config/bootstrap.php';require dirname(__DIR__,2).'/app/admin.php';$admin=admin_require($pdo);
$id=(int)($_GET['id']??0);$post=['id'=>0,'title'=>'','slug'=>'','excerpt'=>'','content'=>'','cover_image'=>'','category_id'=>null,'status'=>'draft'];
if($id){$s=$pdo->prepare('SELECT * FROM posts WHERE id=?');$s->execute([$id]);$post=$s->fetch()?:null;if(!$post){http_response_code(404);exit('Article not found.');}}
$categories=$pdo->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();
admin_header($id?'Edit article':'New article',$admin);admin_show_flash(); ?>
<form class="content-card editor-form" method="post" action="<?= e(admin_url('posts/save.php')) ?>"><?= admin_csrf_field() ?><input type="hidden" name="id" value="<?= (int)$post['id'] ?>"><div class="editor-main"><label>Article title<input name="title" value="<?= e($post['title']) ?>" required maxlength="200"></label><label>URL slug<input name="slug" value="<?= e($post['slug']) ?>" placeholder="generated-from-title"></label><label>Excerpt<textarea name="excerpt" rows="3"><?= e($post['excerpt']) ?></textarea></label><label>Article content<textarea name="content" rows="18" required><?= e($post['content']) ?></textarea></label></div><aside class="editor-side"><label>Status<select name="status"><option value="draft" <?= $post['status']==='draft'?'selected':'' ?>>Draft</option><option value="published" <?= $post['status']==='published'?'selected':'' ?>>Published</option></select></label><label>Category<select name="category_id"><option value="">Uncategorized</option><?php foreach($categories as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (int)$post['category_id']===(int)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach ?></select></label><label>Cover image URL<input name="cover_image" value="<?= e($post['cover_image']) ?>" placeholder="https://…"></label><a href="<?= e(admin_url('media/')) ?>">Browse media library</a><button class="button" type="submit">Save article</button><a class="subtle-link" href="<?= e(admin_url('posts/')) ?>">Cancel</a></aside></form><?php if($id): ?><form method="post" action="<?= e(admin_url('posts/delete.php')) ?>" onsubmit="return confirm('Delete this article permanently?')"><?= admin_csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>"><button class="button danger">Delete article</button></form><?php endif ?><?php admin_footer(); ?>
